bool IsActionSuccess(const std::string& s){return s.rfind("Could not",0)!=0&&s.rfind("No ",0)!=0&&s.rfind("Open ",0)!=0&&s.rfind("BlueStacks installation",0)!=0&&s.rfind("fsutil failed",0)!=0&&s.rfind("DNS cache could not",0)!=0;}
void ApplyOne(const ModuleInfo& m,bool feedback=true){if(m.id==ModuleId::EmulatorGuide){MessageBoxW(mainWnd,L"Start BlueStacks, MSI App Player, or LDPlayer, then press Scan. If ADB is online, the panel checks whether Free Fire is running. The panel only changes emulator process priority while that emulator is open; the GPU preference also requires BlueStacks to be running.\n\nFor FPS, use Free Fire's and the emulator's official graphics settings. Choose 90 FPS only if that option is shown and your display/emulator can sustain it. If the game or emulator caps the game at 60, this panel cannot safely unlock 70/90 or promise extra FPS. It does not edit game files, inject into the game, or alter game memory.",L"Emulator & Free Fire performance",MB_OK|MB_ICONINFORMATION);SetStatus(L"Opened the emulator and Free Fire performance guide.");return;}if(m.id==ModuleId::InputGuide){MessageBoxW(mainWnd,L"There is no universal Windows switch that removes mouse or network latency. Keep pointer acceleration off only if that matches your preference; for emulator input lag, compare FPS/VSync and emulator input settings. DNS flush only clears name-lookup cache and does not lower in-game ping. This guide makes no system changes.",L"Mouse delay & network latency guide",MB_OK|MB_ICONINFORMATION);SetStatus(L"Opened the input and network guide.");return;}if(active[(size_t)m.id]){if(!m.reversible)return;auto result=UndoModule(m.id);bool ok=IsActionSuccess(result);if(ok)active[(size_t)m.id]=false;std::wstring w(result.begin(),result.end());SetStatus(w);if(feedback)ShowActionResult(mainWnd,m.name,w,ok);return;}
 if(m.id==ModuleId::Temp){if(MessageBoxW(mainWnd,L"This removes files in the current user's TEMP folder. Files in use will be skipped. Continue?",L"Confirm temporary-file cleanup",MB_YESNO|MB_ICONWARNING)!=IDYES)return;}
 auto result=ApplyModule(m.id);std::wstring w(result.begin(),result.end());bool ok=IsActionSuccess(result);if(ok){active[(size_t)m.id]=true;if(m.id==ModuleId::Dns||m.id==ModuleId::Temp)active[(size_t)m.id]=false;}SetStatus(w);if(feedback)ShowActionResult(mainWnd,m.name,w,ok);
}
void Preset(bool v2){const auto& ms=Modules();std::vector<ModuleId> ids=v2?std::vector<ModuleId>{ModuleId::Dvr,ModuleId::Telemetry,ModuleId::Ntfs,ModuleId::Dns,ModuleId::Power,ModuleId::Temp,ModuleId::Mouse,ModuleId::Priority,ModuleId::Gpu,ModuleId::GameMode}:std::vector<ModuleId>{ModuleId::Dvr,ModuleId::Mouse,ModuleId::GameMode,ModuleId::Dns};for(auto id:ids){auto it=std::find_if(ms.begin(),ms.end(),[&](const ModuleInfo&m){return m.id==id;});if(it!=ms.end()&&!active[(size_t)id])ApplyOne(*it,false);}SetStatus(v2?L"Optimize V2 preset applied. Review each module status below.":L"Optimize V1 preset applied. Review each module status below.");}
